import{_ as t,o as a,c as s,a3 as r}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"System breakdown","description":"","frontmatter":{},"headers":[],"relativePath":"project/system.md","filePath":"project/system.md","lastUpdated":1794433168000}'),n={name:"project/system.md"};function o(i,e,d,c,l,p){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="system-breakdown" tabindex="-1">System breakdown <a class="header-anchor" href="#system-breakdown" aria-label="Permalink to &quot;System breakdown&quot;">​</a></h1><p><strong>Proposed application architecture.</strong> The documentation site and synthetic contract labs exist; the runtime below does not yet exist in this repository. The <a href="./../reuse/">reuse map</a> identifies the implementation starting points.</p><h2 id="seven-modules-a-small-number-of-process-roles" tabindex="-1">Seven modules, a small number of process roles <a class="header-anchor" href="#seven-modules-a-small-number-of-process-roles" aria-label="Permalink to &quot;Seven modules, a small number of process roles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Owns</th><th>Starting point</th></tr></thead><tbody><tr><td>Research interface</td><td>Chat, evidence, library, jobs and review</td><td>SvelteKit/TypeScript; workshop protocol behavior</td></tr><tr><td>API</td><td>Authenticated commands, sessions, HTTP/SSE delivery</td><td>Rust/Axum/Tokio; current Ordo adapter boundaries</td></tr><tr><td>Retrieval</td><td>Lexical/vector candidates, authorized graph expansion and citation packets</td><td>Rust adapters; explicit evaluation before semantic claims</td></tr><tr><td>Knowledge library</td><td>Sources, identities, claims, review and revisions</td><td>Rust/SQLite; historical graph lifecycle, redesigned invariants</td></tr><tr><td>Ingestion</td><td>Parsing, extraction and identity proposals</td><td>Bounded capability workers; reviewed executor steps</td></tr><tr><td>Workflow engine</td><td>Plans, tasks, leases, idempotency and replay</td><td>Historical Rust kernel/event log with identified repairs</td></tr><tr><td>Capability workers</td><td>Models, speech, OCR, media and native acceleration</td><td>Rust/Swift processes with versioned contracts</td></tr></tbody></table><h2 id="hosted-process-boundary" tabindex="-1">Hosted process boundary <a class="header-anchor" href="#hosted-process-boundary" aria-label="Permalink to &quot;Hosted process boundary&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Browser: Chat / Evidence / Library / Jobs / Review</span></span>
<span class="line"><span>                         |</span></span>
<span class="line"><span>          Stateless Rust API + built web assets</span></span>
<span class="line"><span>                         |</span></span>
<span class="line"><span>       Private Rust store / command + event boundary</span></span>
<span class="line"><span>               |                         |</span></span>
<span class="line"><span>       Durable operational DB    Published library + objects</span></span>
<span class="line"><span>               |</span></span>
<span class="line"><span>       Leased bounded workers → validated results</span></span></code></pre></div><p>The private store owns transactions; it does not expose arbitrary SQL. The API and workers access it through authenticated, scoped commands. Their local caches and temporary buffers are not the only copy of accepted state. This is a small same-codebase deployment, not a mandate for seven microservices.</p><p>The store is a stateful backing resource. It is not horizontally replicated by starting more SQLite writers on shared network storage. Scale bounded compute workers first; measure contention and memory before redesigning storage. <a href="./../engineering/twelve-factor">Twelve-factor decisions</a> document the hosted boundary and local exception.</p><h2 id="one-authority-per-kind-of-state" tabindex="-1">One authority per kind of state <a class="header-anchor" href="#one-authority-per-kind-of-state" aria-label="Permalink to &quot;One authority per kind of state&quot;">​</a></h2><p>Only the Rust store can commit canonical changes. A worker returns a result envelope and artifacts; permission-bearing identity, library scope and review decisions come from the server, not model text or browser context. The UI renders authorized projections.</p><p>Within a writable library, publication records and publication events share one transaction. Within operational state, run admission and its events share one transaction. No atomic transaction is assumed across independent databases: a run references an already published immutable library revision, which is retained while citations depend on it.</p><p>Task execution is at least once. Result acceptance is idempotent and lease-fenced. External providers and side effects are not automatically exactly once. Retry policy distinguishes safe deterministic work from paid generation that has already produced output.</p><h2 id="two-deployment-profiles" tabindex="-1">Two deployment profiles <a class="header-anchor" href="#two-deployment-profiles" aria-label="Permalink to &quot;Two deployment profiles&quot;">​</a></h2><p><strong>Local authoring:</strong> a Mac or Linux workstation owns source imports, drafts and review. It may embed the store in one process for convenience. This is an explicit stateful appliance profile, not strict stateless hosting. The same domain and schema contracts apply.</p><p><strong>Hosted demonstration:</strong> a private store serves an approved research snapshot and separate operational conversation/job records. It does not independently author the canonical research graph in v1. Public chat cannot ingest arbitrary files, install workers or approve drafts.</p><p>Publish revisions through verified export/import. Retain evidence needed by older conversations. Mac processing capability is optional: the hosted library must still open when the Mac is offline. Inference/query capabilities that are unavailable are reported honestly rather than silently replaced.</p><h2 id="first-vertical-slice" tabindex="-1">First vertical slice <a class="header-anchor" href="#first-vertical-slice" aria-label="Permalink to &quot;First vertical slice&quot;">​</a></h2><p>A synthetic source becomes an artifact and mention, an unresolved identity becomes a review decision, and an approved changeset becomes a published revision. Retrieval selects authorized evidence; a worker produces an answer; the API streams recorded outcomes and citations. Each transition can be inspected without reading an entire business platform.</p><p>See <a href="./knowledge">knowledge</a>, <a href="./plugins">workers</a>, <a href="./streaming">streaming</a>, <a href="./acceptance">acceptance</a> and the <a href="./roadmap">dependency-ordered roadmap</a>.</p>`,19)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
